INSERT INTO visitas (id, notificacion_id, migrated_from_glide, resultado, observaciones, ubicacion_lat, ubicacion_lng, foto_url, fecha) VALUES ('5e43bc11-ebe4-48d3-b0e4-4cebe1726a98', '6d9e4588-6d4d-48c9-97d3-73c1d0ae52bb', 1, 'No Atiende', NULL, NULL, NULL, NULL, '2025-11-05 17:23:37');
INSERT INTO visitas (id, notificacion_id, migrated_from_glide, resultado, observaciones, ubicacion_lat, ubicacion_lng, foto_url, fecha) VALUES ('4a4982b4-cb22-4f75-84b5-e79d16c81946', '6d9e4588-6d4d-48c9-97d3-73c1d0ae52bb', 1, 'No Atiende', 'Por averiguaciones recabadas en la zona los vecinos me informan que el destinatario hace más de 7 años no vive en el lugar y que la propiedad donde vivía La vendió actualmente existen ocho vivienda construida en lo que era la propiedad que pertenecía al destinatario por lo que ningunas de las personas que ocupaban las viviendas me quiso recibir debido a ello y tratándose de una zona sumamente peligrosa habida cuenta que había la existencia de varios masculinos en estado de ebriedad y drogados dando vuelta y amenazándome es que procedo a dejar copia por debajo de la puerta en una de las viviendas que fue construida en la propiedad que pertenecía al destinatario así también me informa que el mismo se encontraría viviendo en la provincia de Mendoza', NULL, NULL, NULL, '2025-11-05 17:28:08');
